export async function openOwnersList(page) {
    await page.getByRole("button", { name: "Owners" }).click();
    await page.getByRole("link", { name: "Search" }).click();
}

export async function openOwnerDetail(page, ownerHref) {
    await page.locator(`a[href="${ownerHref}"]`).click();
    await page.getByRole("heading", { name: "Owner Information" }).waitFor({ state: "visible", timeout: 10000 });
}

export async function openAddPetForm(page) {
    await page.getByRole("button", { name: "Add New Pet" }).click();
    await page.getByRole("heading", { name: "Add Pet" }).waitFor({ state: "visible", timeout: 10000 });
}

export async function fillPetNickname(page, nickname) {
    await page.locator("#nickname").fill(nickname);
}
